import {test,expect,type Page,type TestInfo,type Locator} from '@playwright/test';
import {writeFile} from 'node:fs/promises';
import {readFileSync} from 'node:fs';
import {newGame,advance} from '../../src/full/engine.ts';
import {driver} from '../../tests/full-route.mjs';
import {demoCatalog} from '../../src/demo.ts';
import {guideCatalog} from '../src/guidance';
import type {Game} from '../../src/full/types.ts';
import {useJourneyClock,snapshot,activitySnapshot as activity} from './support';

test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const gameDB='chenyuan-playable-v1',localDB='chenyuan-local-experience-v1';
const errors=new WeakMap<Page,string[]>();
function listen(page:Page){if(errors.has(page))return;const rows:string[]=[];errors.set(page,rows);page.on('pageerror',e=>rows.push(e.message));}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({context},info)=>{for(const page of context.pages())if(!page.isClosed()){
  await page.evaluate(()=>{const w=window as any;w.__m03ReleaseWrite?.();w.__m03RestoreFile?.();w.__m03ControlObserver?.disconnect();});
  await info.attach('control-browser-errors',{body:JSON.stringify(errors.get(page)??[]),contentType:'application/json'});
  expect(errors.get(page)??[]).toEqual([]);
}});
async function evidence(info:TestInfo,name:string,data:unknown){const path=info.outputPath(name+'.json');await writeFile(path,JSON.stringify(data,null,2)+'\n');await info.attach(name,{path,contentType:'application/json'});}
async function database(page:Page,name=gameDB){return page.evaluate(name=>new Promise<any>((resolve,reject)=>{
  const q=indexedDB.open(name);q.onupgradeneeded=()=>{q.transaction!.abort();reject(new Error('Readonly UI observation cannot create '+name));};q.onerror=()=>reject(q.error);
  q.onsuccess=()=>{const db=q.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};
    for(const key of db.objectStoreNames){rows[key]=[];const read=tx.objectStore(key).openCursor();read.onsuccess=()=>{if(read.result){rows[key].push({key:read.result.key,value:read.result.value});read.result.continue();}};}
    tx.oncomplete=()=>{const version=db.version;db.close();resolve({version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};
}),name);}
const current=(raw:any)=>raw.rows['full-state'].find((r:any)=>r.key==='current')?.value??null;
async function settings(page:Page){if(!await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'设置',exact:true}).click();await expect(page.getByRole('dialog',{name:'行旅设置',exact:true})).toBeVisible();}
async function closeSettings(page:Page){if(await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'关闭设置',exact:true}).click();}
async function localPanel(page:Page){await settings(page);const box=page.getByTestId('local-records-panel');if(!await box.evaluate(n=>(n as HTMLDetailsElement).open))await box.locator(':scope>summary').click();await expect(page.getByTestId('local-recording')).toBeEnabled();}
async function boot(page:Page,virtual=true){if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.getByTestId('save-status')).toHaveText('尚无存档',{timeout:15000});
  await localPanel(page);if(!await page.getByTestId('local-recording').isChecked())await page.getByTestId('local-recording').check();await expect.poll(async()=>{const r=await database(page,localDB);return r.rows.meta.find((x:any)=>x.key==='state')?.value.preferences.recording;}).toBe(true);await closeSettings(page);
}
async function controlClock(page:Page){await expect(page.getByTestId('action-execution')).toBeVisible();await page.clock.runFor(600);}
async function quietFeedback(page:Page){await page.clock.runFor(32);await page.clock.fastForward(1600);await page.clock.runFor(32);await expect(page.getByTestId('hub-pulse')).toHaveCount(0);await expect(page.getByTestId('action-motion')).toHaveCount(0);}
async function create(page:Page,name='界面控制客',virtual=true){await page.getByLabel('你的道号',{exact:true}).fill(name);await page.getByRole('button',{name:'踏入仙途',exact:false}).click();if(virtual)await controlClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');const game=await snapshot(page);expect(game).toEqual(newGame(name,game.core.runId));return game as Game;}
async function chooseDialog(page:Page,accept:boolean,operation:()=>Promise<unknown>){const dialog=page.waitForEvent('dialog',{timeout:8000}),acting=operation(),opened=await dialog;const message=opened.message();if(accept)await opened.accept();else await opened.dismiss();await acting;expect(message).not.toBe('');return message;}
async function importWelcome(page:Page,fixture:Game){await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'lawful-control-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await controlClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');const after=await snapshot(page);expectImported(fixture,after);await quietFeedback(page);return after as Game;}
function expectImported(fixture:Game,actual:Game){const expected=structuredClone(fixture);expected.core.runId=actual.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=actual.core.runId+':'+expected.core.activeEvent.id;expect(actual).toEqual(expected);}
async function recordFor(page:Page,kind:string,run:string){let found:any[]=[];await expect.poll(async()=>{const raw=await database(page,localDB);found=raw.rows.events.filter((r:any)=>r.value.data.observation.kind===kind&&r.value.data.observation.runId===run);return found.length;}).toBe(1);return found[0].value.data.observation;}
async function holdWrite(page:Page){await page.evaluate(()=>new Promise<void>((resolve,reject)=>{
  const q=indexedDB.open('chenyuan-playable-v1');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction('full-state','readwrite');let held=true,ready=false;const w=window as any;w.__m03ReleaseWrite=()=>held=false;
    const read=()=>{const r=tx.objectStore('full-state').get('current');r.onsuccess=()=>{w.__m03HeldGame=r.result??null;if(!ready){ready=true;resolve();}if(held)read();};};read();tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};
}));}
async function observeControls(page:Page){await page.evaluate(()=>{const w=window as any,seen=new Set<string>(),rows:any[]=[];
  const visit=(node:Node)=>{if(!(node instanceof Element))return;for(const el of node.matches('[data-testid=hub-pulse]')?[node]:node.querySelectorAll('[data-testid=hub-pulse]')){const key=el.getAttribute('data-receipt');if(key&&!seen.has(key)){seen.add(key);rows.push({key,operation:el.getAttribute('data-operation'),text:el.textContent});}}};
  const observer=new MutationObserver(changes=>{for(const c of changes)for(const n of c.addedNodes)visit(n);});observer.observe(document.body,{subtree:true,childList:true});w.__m03ControlRows=rows;w.__m03ControlObserver=observer;
});}
async function picture(page:Page,info:TestInfo,name:string,selector:string){const geometry=await page.locator(selector).evaluateAll(nodes=>nodes.map(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n),dialog=n.closest('dialog[open]'),d=dialog?.getBoundingClientRect();return{text:n.textContent,rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom,height:r.height},font:parseFloat(s.fontSize),opacity:s.opacity,clip:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,dialog:d?{left:d.left,right:d.right,top:d.top,bottom:d.bottom,clientHeight:dialog!.clientHeight,scrollHeight:dialog!.scrollHeight}:null};}));await evidence(info,name+'-geometry',geometry);await page.screenshot({path:info.outputPath(name+'.png')});
  expect(await page.evaluate(()=>document.documentElement.scrollHeight)).toBeLessThanOrEqual(900);for(const r of geometry){expect(r.rect.left).toBeGreaterThanOrEqual(0);expect(r.rect.right).toBeLessThanOrEqual(1440);expect(r.rect.top).toBeGreaterThanOrEqual(0);expect(r.rect.bottom).toBeLessThanOrEqual(900);expect(r.clip,r.text??'').toBe(false);}
}
async function hit(control:Locator){await expect(control).toBeInViewport({ratio:1});expect(await control.evaluate(n=>{const r=n.getBoundingClientRect(),top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return{height:r.height,hit:top===n||!!top&&n.contains(top)};})).toMatchObject({hit:true});expect(await control.evaluate(n=>n.getBoundingClientRect().height)).toBeGreaterThanOrEqual(44);}
async function savedFeedback(page:Page,info:TestInfo,kind:string,operation:string,label:string,before:Game|null){await expect(page.getByTestId('save-status')).toHaveText('已保存');await closeSettings(page);
  await expect.poll(async()=>{await page.clock.runFor(16);const pulse=page.getByTestId('hub-pulse');return await pulse.count()===1&&await pulse.getAttribute('data-operation')===operation&&Number(await pulse.evaluate(n=>getComputedStyle(n).opacity))>.95;}).toBe(true);
  const pulse=page.getByTestId('hub-pulse');await expect(pulse).toContainText(label);await expect(pulse).toContainText('当前进度已保存');expect(await pulse.locator('strong').evaluate(n=>parseFloat(getComputedStyle(n).fontSize))).toBeGreaterThanOrEqual(18);
  const after=await snapshot(page),raw=await database(page),receipts=raw.rows['full-receipts'].filter((r:any)=>r.value.format==='chenyuan-control-receipt'&&r.value.kind===operation&&r.value.mutation.runId===after.core.runId);
  expect(receipts).toHaveLength(1);const receipt=receipts[0],mutation=receipt.value.mutation;expect(receipt.key).toBe(mutation.runId+':'+mutation.commandId);expect(mutation.expectedRunId).toBe(before?.core.runId??null);expect(mutation.expectedRevision).toBe(before?.core.revision??0);expect(after.core.revision).toBe(0);if(before)expect(after.core.runId).not.toBe(before.core.runId);
  expect(raw.rows['full-state'].find((r:any)=>r.key==='activity')).toBeUndefined();const observation=await recordFor(page,kind,after.core.runId);expect(observation.commandId).toBe(mutation.commandId);expect(observation.operation).toBe(operation);expect(observation.replayed).toBe(false);expect(observation.result).toBeNull();
  expect(JSON.parse((await pulse.getAttribute('data-receipt'))!)).toEqual([after.core.runId,mutation.commandId]);const shown=await page.evaluate(()=>(window as any).__m03ControlRows);expect(shown).toHaveLength(1);await picture(page,info,kind+'-saved-control','[data-testid=hub-pulse]');await evidence(info,kind+'-original-control',{before,after,raw,receipt,observation,shown});
  await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');await page.clock.runFor(32);await expect(page.getByTestId('hub-pulse')).toHaveCount(0);await expect(page.getByTestId('action-motion')).toHaveCount(0);expect(await database(page)).toEqual(raw);return{after:after as Game,raw,receipt};
}
async function prepareRestore(page:Page){const d=driver();d.realm();const prepared=await importWelcome(page,d.checkpoints.qi);await page.getByTestId('breakthrough').click();await page.getByTestId('milestone-confirm').click();await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page);await expect(page.locator('[data-testid=training-activity][data-generation="'+a.generation+'"][data-running=true]')).toBeVisible();await page.clock.fastForward(29999);expect(await snapshot(page)).toEqual(prepared);await page.clock.fastForward(1);await expect.poll(async()=>(await activity(page)).completedCycles).toBe(1);expect(await snapshot(page)).toEqual(advance(prepared,a.nextCommand));await expect(page.getByTestId('save-status')).toHaveText('已保存');const raw=await database(page),checkpoint=raw.rows['full-state'].find((r:any)=>r.key==='checkpoint').value;expect(checkpoint.snapshot).toEqual(prepared);await quietFeedback(page);return checkpoint;}

for(const [number,kind,operation,label]of [[1,'new_game','CREATE','此卷初启'],[2,'restart','CREATE','新卷已启'],[3,'import','IMPORT','进度已载入'],[4,'restore','RESTORE','准备已恢复']]as const)
test('M03-C'+number+' '+kind+' has its own explicit UI decision native saved identity and one control feedback without game rewards',async({page},info)=>{
  await boot(page);let checkpoint:any=null,fixture:Game|null=null;if(kind==='restore')checkpoint=await prepareRestore(page);else if(kind!=='new_game'){await create(page,'控制'+kind);await quietFeedback(page);}
  if(kind==='import')fixture=driver('trade','talisman').game;const rawBefore=await database(page),before=current(rawBefore)as Game|null;
  if(kind!=='new_game'){await settings(page);const invoke=()=>kind==='import'?page.getByTestId('import').setInputFiles({name:'confirmed-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))}):page.getByTestId(kind==='restart'?'restart':'restore-checkpoint').click();await chooseDialog(page,false,invoke);expect(await database(page)).toEqual(rawBefore);}
  await observeControls(page);await holdWrite(page);let failure:unknown;
  try{if(kind==='new_game'){await page.getByLabel('你的道号',{exact:true}).fill('控制新卷');await page.getByRole('button',{name:'踏入仙途',exact:false}).click();}
    else await chooseDialog(page,true,()=>kind==='import'?page.getByTestId('import').setInputFiles({name:'confirmed-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))}):page.getByTestId(kind==='restart'?'restart':'restore-checkpoint').click());
    await controlClock(page);await expect(page.getByTestId('save-status')).toHaveText('保存中');expect(await page.evaluate(()=>(window as any).__m03HeldGame)).toEqual(before);await expect(page.getByTestId('hub-pulse')).toHaveCount(0);await expect(page.getByTestId('action-motion')).toHaveCount(0);await evidence(info,kind+'-native-pending',{before,rawBefore,heldGame:await page.evaluate(()=>(window as any).__m03HeldGame)});
  }catch(error){failure=error;}finally{await page.evaluate(()=>(window as any).__m03ReleaseWrite());}if(failure)throw failure;
  const result=await savedFeedback(page,info,kind,operation,label,before);if(kind==='new_game'||kind==='restart')expect(result.after).toEqual(newGame(kind==='new_game'?'控制新卷':before!.core.player.name,result.after.core.runId));else expectImported(kind==='import'?fixture!:checkpoint.snapshot,result.after);
  if(kind==='restore'){expect(result.raw.rows['full-state'].find((r:any)=>r.key==='checkpoint').value).toEqual(checkpoint);expect(result.raw.rows['full-state'].find((r:any)=>r.key==='checkpoint-owner').value).toEqual({format:'chenyuan-checkpoint-scope',version:1,runId:result.after.core.runId,sourceRunId:checkpoint.sourceRunId,sourceRevision:checkpoint.sourceRevision,kind:checkpoint.kind});expect(result.raw.rows['full-state'].find((r:any)=>r.key==='previous').value).toEqual(before);const priorActivity=rawBefore.rows['full-state'].find((r:any)=>r.key==='activity').value;expect(result.raw.rows['full-backups'].find((r:any)=>r.key==='restoration/'+result.receipt.value.mutation.commandId+'/activity').value).toEqual(priorActivity);for(const row of rawBefore.rows['full-backups'])expect(result.raw.rows['full-backups'].find((r:any)=>r.key===row.key)).toEqual(row);}else expect(result.raw.rows['full-state'].find((r:any)=>r.key==='checkpoint')).toBeUndefined();
});

test('M03-C5 local report preview cancellation and explicit download preserve the full Game and disclose a private non-save snapshot',async({page},info)=>{
  const requests:string[]=[],downloads:string[]=[],origin=new URL(info.project.use.baseURL??'http://127.0.0.1:4173').origin;page.on('request',r=>{if(r.method()!=='GET'||new URL(r.url()).origin!==origin)requests.push(r.method()+':'+r.url());});page.on('download',d=>downloads.push(d.suggestedFilename()));
  await boot(page);const game=await create(page,'不应导出的私密道号');await recordFor(page,'new_game',game.core.runId);const before=await database(page);await localPanel(page);
  await expect(page.getByTestId('local-download')).toHaveCount(0);await page.getByTestId('local-export-preview').focus();await page.keyboard.press('Enter');const preview=page.getByTestId('local-export-ready');await expect(preview).toBeFocused();await expect(preview).toContainText('文件不是游戏存档，不能恢复进度');await expect(preview).toContainText('不会自动发送');await expect(preview).toContainText('预览之后的新记录不在本次文件中');
  await page.getByTestId('local-export-cancel').focus();await page.keyboard.press('Enter');await expect(preview).toHaveCount(0);await expect(page.getByTestId('local-export-preview')).toBeFocused();expect(downloads).toEqual([]);expect(await database(page)).toEqual(before);
  await page.getByTestId('local-export-preview').click();await expect(preview).toBeFocused();const ready=await database(page,localDB);await hit(page.getByTestId('local-download'));await picture(page,info,'report-preview','[data-testid=local-export-ready]');const waiting=page.waitForEvent('download');await page.getByTestId('local-download').click();const file=await waiting;expect(file.suggestedFilename()).toBe('尘缘问道-本地试玩记录与偏好.json');const report=JSON.parse(readFileSync((await file.path())!,'utf8')),serialized=JSON.stringify(report);
  expect(report.format).toBe('chenyuan-local-playtest');expect(report.notASave).toBe(true);expect(report.policy).toMatchObject({automaticallyUploaded:false,containsPlayerName:false,containsSave:false,containsDeviceFingerprint:false});expect(report.persistent.available).toBe(true);expect(report.persistent.entries.length).toBeGreaterThan(0);expect(report.persistent.entries.map((r:any)=>r.record)).toEqual(ready.rows.events.map((r:any)=>r.value.data));for(const privateField of ['不应导出的私密道号','learnedSkills','journal','userAgent'])expect(serialized).not.toContain(privateField);expect(report.persistent.entries.every((r:any)=>r.record.seed===null&&r.record.sessionId&&Number.isInteger(r.record.elapsedMs))).toBe(true);expect(downloads).toHaveLength(1);expect(requests).toEqual([]);expect(await database(page)).toEqual(before);
  await page.getByTestId('local-export-cancel').click();await chooseDialog(page,true,()=>page.getByTestId('import').setInputFiles({name:'not-a-game.json',mimeType:'application/json',buffer:Buffer.from(serialized)}));await controlClock(page);await expect(page.getByTestId('settings-error')).toBeVisible();expect(await database(page)).toEqual(before);await evidence(info,'private-report-controls',{game,before,report,downloads,requests});
});

async function finishCycle(page:Page,info:TestInfo,name:string,period:number){await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page),before=await snapshot(page);expect(a.cycleMs).toBe(period);await expect(page.locator('[data-testid=training-activity][data-running=true][data-generation="'+a.generation+'"]')).toBeVisible();await expect(page.getByTestId('training-countdown')).toHaveText((period/1000).toFixed(1)+' 秒');const accepted=await database(page);await page.clock.fastForward(period-1);expect(await snapshot(page)).toEqual(before);expect(await database(page)).toEqual(accepted);await page.clock.fastForward(1);await expect.poll(async()=>(await activity(page)).completedCycles).toBe(1);const after=await snapshot(page),raw=await database(page);expect(after).toEqual(advance(before,a.nextCommand));expect((await activity(page)).status).toBe('stopped');const receipt=raw.rows['full-receipts'].filter((r:any)=>r.key===a.runId+':'+a.nextCommand.commandId);expect(receipt).toHaveLength(1);await evidence(info,name,{before,accepted,activity:a,after,raw,receipt});return after as Game;}
test('M03-C6 recording disabled persists across refresh without backfilling and re-enabling captures only the next explicitly arranged action',async({page},info)=>{
  await boot(page);const first=await create(page);await recordFor(page,'new_game',first.core.runId);await localPanel(page);await page.getByTestId('local-recording').uncheck();await expect(page.getByTestId('local-data-status')).toContainText('本地试玩记录已关闭');const off=await database(page,localDB),before=await database(page);expect(off.rows.meta.find((r:any)=>r.key==='state').value.preferences.recording).toBe(false);await closeSettings(page);expect(await database(page)).toEqual(before);
  await page.getByTestId('leave').click();await page.getByTestId('milestone-confirm').click();const afterChoice=await finishCycle(page,info,'recording-off-choice',6000);expect((await database(page,localDB)).rows.events).toEqual(off.rows.events);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(await snapshot(page)).toEqual(afterChoice);await localPanel(page);await expect(page.getByTestId('local-recording')).not.toBeChecked();expect((await database(page,localDB)).rows.events).toEqual(off.rows.events);
  await page.getByTestId('local-recording').check();await expect(page.getByTestId('local-data-status')).toContainText('设置已保存');const reenabled=await database(page,localDB);expect(reenabled.rows.events).toEqual(off.rows.events);await closeSettings(page);await page.getByTestId('return-cave').click();const afterTravel=await finishCycle(page,info,'recording-enabled-travel',6000);let records:any[]=[];await expect.poll(async()=>{records=(await database(page,localDB)).rows.events;return records.length;}).toBe(off.rows.events.length+1);const added=records.at(-1).value.data.observation;expect(added).toMatchObject({kind:'action',operation:'TRAVEL',runId:afterTravel.core.runId,replayed:false});expect(records.filter((r:any)=>r.value.data.observation.operation==='CHOOSE')).toHaveLength(0);await localPanel(page);await expect(page.getByTestId('local-recording')).toBeChecked();await evidence(info,'recording-epochs',{off,reenabled,records,afterChoice,afterTravel});
});

test('M03-C7 keyboard help exposes every current guide and Escape returns focus to its exact public opener without writing Game',async({page},info)=>{
  await boot(page);await create(page);const before=await database(page),opener=page.getByTestId('game-settings');await opener.focus();await page.keyboard.press('Enter');await expect(page.getByRole('dialog',{name:'行旅设置',exact:true})).toBeVisible();await page.getByTestId('gameplay-help-entry').focus();await page.keyboard.press('Enter');const help=page.getByRole('dialog',{name:'玩法帮助',exact:true});await expect(help).toBeVisible();await expect(page.locator('#gameplay-help-title')).toBeFocused();await expect(page.getByRole('dialog',{name:'行旅设置',exact:true})).toBeHidden();
  for(const guide of guideCatalog){const section=help.locator('section').filter({has:page.getByRole('heading',{name:guide.title,exact:true})});await expect(section).toHaveCount(1);expect(await section.locator('p').textContent()).toBe(guide.body);expect(await section.locator('p').evaluate(n=>parseFloat(getComputedStyle(n).fontSize))).toBeGreaterThanOrEqual(18);}expect(await help.locator('section').count()).toBe(guideCatalog.length);await hit(help.getByRole('button',{name:'关闭玩法帮助',exact:true}));await picture(page,info,'help-public-opener','[data-testid=guide-toggle]');await page.keyboard.press('Escape');await expect(help).toBeHidden();await expect(opener).toBeFocused();expect(await database(page)).toEqual(before);await evidence(info,'help-complete-catalogue',{guides:guideCatalog,before,after:await database(page),focused:await page.evaluate(()=>document.activeElement?.getAttribute('data-testid'))});
});

test('M03-C8 the demo menu exposes all nine lawful node scopes while normal Game local records and tracking remain isolated',async({page,context},info)=>{
  await boot(page,false);const normal=await create(page,'正常卷隔离客',false);await recordFor(page,'new_game',normal.core.runId);await localPanel(page);await page.getByTestId('local-refresh').click();const before=await database(page),local=await database(page,localDB),tracking=await page.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'));await page.getByTestId('demo-menu-open').click();const menu=page.getByRole('dialog',{name:'演示节点',exact:true});await expect(menu).toBeVisible();await expect(page.locator('#demo-menu-title')).toBeFocused();expect(await menu.locator('[data-testid^=demo-node-]').count()).toBe(9);
