async function holdFile(page:Page){await page.evaluate(()=>{const original=File.prototype.text,w=window as any;w.__m03File=null;w.__m03RestoreFile=()=>File.prototype.text=original;File.prototype.text=function(){if(this.name!=='m03-delayed.json')return original.call(this);const file=this;return new Promise<string>((resolve,reject)=>{w.__m03File={released:false,readComplete:false,release:async()=>{w.__m03File.released=true;try{const text=await original.call(file);resolve(text);w.__m03File.readComplete=true;}catch(error){reject(error);w.__m03File.readComplete=true;}},reject:()=>{w.__m03File.readComplete=true;reject(new DOMException('controlled unreadable file','NotReadableError'));}};});};});}
async function chooseHeld(page:Page,fixture:Game,welcome=false){const input=welcome?page.getByLabel('导入已有存档',{exact:true}):page.getByTestId('import');await input.setInputFiles({name:'m03-delayed.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(fixture))});await expect.poll(()=>page.evaluate(()=>!!(window as any).__m03File)).toBe(true);}
async function lateRelease(page:Page){const dialogs:string[]=[];const reject=async(d:any)=>{dialogs.push(d.message());await d.dismiss();};page.on('dialog',reject);try{await page.evaluate(async()=>{await (window as any).__m03File.release();});await expect.poll(()=>page.evaluate(()=>(window as any).__m03File.readComplete)).toBe(true);await page.clock.runFor(600);await page.clock.runFor(32);await expect(page.getByTestId('action-execution')).toHaveCount(0);expect(dialogs).toEqual([]);}finally{page.off('dialog',reject);}return dialogs;}
