async function evidence(info:TestInfo,name:string,value:unknown){const path=info.outputPath(name+'.json');writeFileSync(path,JSON.stringify(value,null,2)+'\n');await info.attach(name,{path,contentType:'application/json'});}
async function frame(page:Page,info:TestInfo,label:string,selector:string){const geometry=await page.locator(selector).evaluateAll(nodes=>nodes.map(n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n),top=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2),button=n instanceof HTMLButtonElement;return{text:n.textContent,tag:n.tagName,button,font:parseFloat(s.fontSize),left:r.left,right:r.right,top:r.top,bottom:r.bottom,height:r.height,hit:top===n||!!top&&n.contains(top),clipped:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1};}));await evidence(info,label+'-geometry',geometry);await page.screenshot({path:info.outputPath(label+'.png')});for(const r of geometry){expect(r.left).toBeGreaterThanOrEqual(0);expect(r.right).toBeLessThanOrEqual(1440);expect(r.top).toBeGreaterThanOrEqual(0);expect(r.bottom).toBeLessThanOrEqual(900);expect(r.clipped,r.text??'').toBe(false);expect(r.font).toBeGreaterThanOrEqual(r.tag==='SMALL'?14:18);if(r.button){expect(r.height).toBeGreaterThanOrEqual(44);expect(r.hit,r.text??'').toBe(true);}}expect(await page.evaluate(()=>document.documentElement.scrollHeight)).toBeLessThanOrEqual(900);}
async function raw(page:Page,name=main){return page.evaluate(name=>new Promise<any>((resolve,reject)=>{const q=indexedDB.open(name);q.onupgradeneeded=()=>{q.transaction!.abort();reject(new Error('Readonly observation cannot create '+name));};q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};for(const store of db.objectStoreNames){rows[store]=[];const c=tx.objectStore(store).openCursor();c.onsuccess=()=>{if(c.result){rows[store].push({key:c.result.key,value:c.result.value});c.result.continue();}};}tx.oncomplete=()=>{const version=db.version;db.close();resolve({version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};}),name);}
function value(data:any,key:string){return data.rows['full-state'].find((r:any)=>r.key===key)?.value??null;}
function meta(data:any){return data.rows.meta.find((r:any)=>r.key==='state').value;}
