function imported(source:any,actual:any){const expected=structuredClone(source);expected.core.runId=actual.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=actual.core.runId+':'+expected.core.activeEvent.id;expect(actual).toEqual(expected);}
