function legacy(stage:'opening'|'qi'|'battle'){let game=createAdventure('旧卷迁移客','m03-legacy-'+stage),checkpoint:any=null;const receipts:any[]=[];const act=(action:any)=>{const command={...action,commandId:'legacy-'+game.core.revision,runId:game.core.runId,expectedRevision:game.core.revision};if(action.type==='BREAKTHROUGH')checkpoint=structuredClone(game);game=advanceLegacy(game,command);receipts.push({key:command.runId+':'+command.commandId,value:{fingerprint:canonicalFingerprint(command),revision:game.core.revision}});};if(stage!=='opening')for(const action of [{type:'CHOOSE',choice:'leave'},{type:'TRAVEL',location:'cave'},{type:'CULTIVATE',method:'natural',count:5},{type:'BREAKTHROUGH'},{type:'SCHOOL',school:'sword'}])act(action);if(stage==='battle')for(const action of [{type:'TRAVEL',location:'wilderness'},{type:'ENCOUNTER',enemy:'wolf'},{type:'BATTLE',move:'attack'}])act(action);return{current:game,checkpoint,receipts};}
async function seedLegacyDatabase(page:Page,fixture:ReturnType<typeof legacy>){await page.route('**/matrix-native-legacy-seed-only',r=>r.fulfill({status:200,contentType:'text/html',body:'<!doctype html><title>isolated native legacy fixture</title>'}));await page.goto('/matrix-native-legacy-seed-only');await page.evaluate(f=>new Promise<void>((resolve,reject)=>{const q=indexedDB.open('chenyuan-playable-v1',1);q.onupgradeneeded=()=>{q.result.createObjectStore('state');q.result.createObjectStore('receipts');};q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction(['state','receipts'],'readwrite');tx.objectStore('state').put(f.current,'current');if(f.checkpoint)tx.objectStore('state').put(f.checkpoint,'checkpoint');for(const row of f.receipts)tx.objectStore('receipts').put(row.value,row.key);tx.oncomplete=()=>{db.close();resolve();};tx.onabort=()=>{db.close();reject(tx.error);};};}),fixture);return raw(page);}
