 test('demo reload, reset and typed export/import stay separate from normal saves',async({page},info)=>{
  const initial=await loaded(page,'battle-talisman');const progressed=await cycle(page,info,'typed-demo-one-turn',3000,()=>page.getByTestId('attack').click());expect(progressed.core.revision).toBe(1);const savedRaw=await raw(page,(await demoDatabase(page))!);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(await demoGame(page)).toEqual(progressed);expect(await raw(page,(await demoDatabase(page))!)).toEqual(savedRaw);await settings(page);const waiting=page.waitForEvent('download');await page.getByRole('button',{name:'导出当前进度',exact:true}).click();const file=await waiting,text=fs.readFileSync((await file.path())!,'utf8'),saved=JSON.parse(text);expect(saved.format).toBe('chenyuan-demo-save');expect(saved.game).toEqual(progressed);await closeSettings(page);await resetNode(page);expect((await demoGame(page)).core.runId).not.toBe(progressed.core.runId);expect(normalized(await demoGame(page))).toEqual(normalized(initial));await settings(page);await expect(page.getByTestId('import')).toBeEnabled();page.once('dialog',d=>d.accept());await page.getByTestId('import').setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await finishControl(page);await expect(page.getByTestId('settings-save-status')).toHaveText('已保存');expect(normalized(await demoGame(page))).toEqual(normalized(progressed));const before=await demoGame(page),beforeInvalid=await raw(page,(await demoDatabase(page))!);await page.getByTestId('import').setInputFiles({name:'ordinary.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(before))});await expect(page.getByTestId('settings-error')).toContainText('演示存档');expect(await demoGame(page)).toEqual(before);expect(await raw(page,(await demoDatabase(page))!)).toEqual(beforeInvalid);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);await closeSettings(page);await page.getByTestId('demo-normal').click();await expect(page.getByRole('button',{name:'踏入仙途'})).toBeEnabled();await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await finishRejectedControl(page);await expect(page.getByTestId('error')).toBeVisible();await expect(page.getByTestId('realm')).toHaveCount(0);await evidence(info,'typed-demo-boundary',{initial,progressed,saved,beforeInvalid,normalDatabases:await databases(page)});
